create table if not exists public.content_usage_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id),user_id uuid references public.profiles(id),project_id uuid references public.content_projects(id),request_id uuid,session_id text,kind text not null check(kind in('text_generation','image_generation','regeneration','local_adjustment','failure')),provider text,model text,units jsonb not null default '{}',error_type text,created_at timestamptz not null default now());
create index if not exists content_usage_org_created_idx on public.content_usage_events(organization_id,created_at desc);alter table public.content_usage_events enable row level security;create policy content_usage_select on public.content_usage_events for select using(public.is_org_member(organization_id));create policy content_usage_insert on public.content_usage_events for insert with check(public.has_org_role(organization_id,array['owner','admin','sales']::public.member_role[]));
create table if not exists public.operational_files(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),operational_document_id uuid not null references public.operational_documents(id),request_id uuid not null,version integer not null,content_hash text not null,storage_path text not null,mime_type text not null default 'application/pdf',size_bytes bigint not null check(size_bytes>0 and size_bytes<=20971520),branding_snapshot jsonb not null default '{}',created_by uuid references public.profiles(id),created_at timestamptz not null default now(),unique(organization_id,request_id),unique(organization_id,operational_document_id,content_hash));
create index if not exists operational_files_document_idx on public.operational_files(organization_id,operational_document_id,version desc);alter table public.operational_files enable row level security;create policy operational_files_select on public.operational_files for select using(public.is_org_member(organization_id));create policy operational_files_insert on public.operational_files for insert with check(public.has_org_role(organization_id,array['owner','admin','sales']::public.member_role[]));
create unique index if not exists operational_order_source_unique on public.operational_documents(organization_id,source_document_id) where type='service_order' and source_document_id is not null and deleted_at is null;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('operational-pdfs','operational-pdfs',false,20971520,array['application/pdf'])on conflict(id)do nothing;create policy operational_pdfs_read on storage.objects for select using(bucket_id='operational-pdfs' and public.is_org_member((storage.foldername(name))[1]::uuid));create policy operational_pdfs_write on storage.objects for insert with check(bucket_id='operational-pdfs' and public.has_org_role((storage.foldername(name))[1]::uuid,array['owner','admin','sales']::public.member_role[]));
